(()=>{const c=document.getElementById('siteCursor');if(!c||!window.matchMedia('(hover:hover) and (pointer:fine)').matches)return;c.classList.add('is-visible');let inter=false;const sel='a,button,[role="button"],input,select,textarea,summary,[tabindex]:not([tabindex="-1"])';document.addEventListener('pointerover',e=>{inter=!!e.target.closest?.(sel);c.classList.toggle('is-interactive',inter)},{passive:true});document.addEventListener('pointerout',e=>{inter=!!e.relatedTarget?.closest?.(sel);c.classList.toggle('is-interactive',inter)},{passive:true});window.addEventListener('mousemove',e=>{const s=inter?1.12:1;c.style.transform=`translate3d(${e.clientX-9}px,${e.clientY-9}px,0) scale(${s})`},{passive:true});window.addEventListener('mouseleave',()=>c.style.opacity='0');window.addEventListener('mouseenter',()=>c.style.opacity='1')})();
